#!/usr/bin/env node
/**
 * 生成物来源与数据表不变量校验
 *
 * ## 为什么需要
 *
 * - 多个表面数据文件的头注曾声称「Generated by tools/generate-*.mjs」，而
 *   仓库里没有 `tools/`。读代码的人信了这个头注就会以为「不能手改，要改
 *   生成器」，实际上既没有生成器、也没有任何东西校验这张表。声明与事实相反
 *   比没有声明更糟。
 * - 巨量数据表（webgl-surface 上万行）的损坏不会让任何测试立刻变红，只会在
 *   运行期表现为表面缺失。这里只做**稳定不变量**：导出存在、冻结、非空、
 *   成员行形状合法、同类成员不重名。条目数与成员名会随采集基准更新，不能
 *   拿来卡门禁，否则每轮无害重构都要误报。
 *
 * ## 检查项
 *
 * 1. 悬空来源：`src/**`、`scripts/**` 里引用 `tools/` 生成器而该文件不存在；
 * 2. 数据表：CODECS / SPEECH / WEBGL / XR 四张表的结构不变量；
 * 3. 代码型生成物的导出标记（finalize-worker-surface-order / install-webgl /
 *    install-svg-basic-attribute-elements）。
 *
 * 用法：`npm run check:generated`，失败非零退出。
 */

import { existsSync } from 'node:fs';
import { readFile, readdir } from 'node:fs/promises';
import process from 'node:process';
import { fileURLToPath, pathToFileURL } from 'node:url';

const REPO_ROOT = new URL('../', import.meta.url);

/** 悬空来源扫描的目录（相对仓库根）。 */
const SCAN_DIRECTORIES = ['src', 'scripts'];

/**
 * 匹配对生成器的引用。
 *
 * 注意：本文件自身的源码会被扫描，所以这里不能出现形如 `tools/生成器名.mjs`
 * 的字面量——注释里也一律写成「`tools/` 生成器」。
 */
const TOOLS_REFERENCE = /tools\/(generate-[\w.-]+\.mjs)/g;

/** 表面数据表规格。shape 决定用哪套结构校验。 */
const DATA_TABLES = Object.freeze([
  {
    path: 'src/surface/api/codecs/codecs-surface.js',
    exportName: 'CODECS_SURFACES',
    shape: 'interface',
  },
  {
    path: 'src/surface/api/speech/speech-surface.js',
    exportName: 'SPEECH_SURFACES',
    shape: 'interface',
  },
  {
    path: 'src/surface/api/webgl/webgl-surface.js',
    exportName: 'WEBGL_SURFACES',
    shape: 'webgl',
  },
  {
    path: 'src/surface/api/xr/xr-core-surface.js',
    exportName: 'XR_CORE_SURFACES',
    shape: 'interface',
  },
]);

/**
 * 机器展开的代码型生成物：只校验导出标记。
 *
 * 标记取「导出声明」而不是行号/函数体——重命名导出必然要同步改调用方，
 * 不算无害重构；函数体怎么改则不受约束。
 */
const FUNCTION_ARTIFACTS = Object.freeze([
  {
    path: 'src/surface/install/finalize-worker-surface-order.js',
    marker: 'export function finalizeWorkerSurfaceOrder(',
  },
  {
    path: 'src/surface/install/install-webgl.js',
    marker: 'export function installWebGL(',
  },
  {
    path: 'src/surface/install/install-svg-basic-attribute-elements.js',
    marker: 'export function installSVGBasicAttributeElementMembers(',
  },
]);

const MEMBER_KINDS = new Set(['accessor', 'method', 'iterator', 'constant', 'constructor', 'tag']);
const WEBGL_FIELDS = new Set(['accessors', 'constants', 'methods', 'members']);

function isPlainObject(value) {
  return value !== null && typeof value === 'object' && !Array.isArray(value);
}

/** 成员行统一形状：`[kind, name?, arity?]`；constructor/tag 无名称。 */
function checkMemberRows(rows, label, problems) {
  if (!Array.isArray(rows) || rows.length === 0) {
    problems.push(`${label}: 必须是非空数组`);
    return;
  }
  const seen = new Set();
  for (const row of rows) {
    if (!Array.isArray(row) || row.length === 0 || typeof row[0] !== 'string') {
      problems.push(`${label}: 成员行必须是 [kind, name?...] 数组`);
      continue;
    }
    const kind = row[0];
    if (!MEMBER_KINDS.has(kind)) {
      problems.push(`${label}: 未知成员类型 ${JSON.stringify(kind)}`);
      continue;
    }
    if (kind === 'accessor' || kind === 'method' || kind === 'iterator' || kind === 'constant') {
      if (typeof row[1] !== 'string' || row[1] === '') {
        problems.push(`${label}: ${kind} 成员缺少名称`);
        continue;
      }
      if (
        (kind === 'method' || kind === 'iterator' || kind === 'constant')
        && row[2] !== undefined
        && !Number.isSafeInteger(row[2])
      ) {
        problems.push(`${label}: ${kind} ${row[1]} 的第三个元素不是整数`);
      }
    }
    const key = `${kind}:${row[1] ?? ''}`;
    if (seen.has(key)) problems.push(`${label}: 重复成员 ${key}`);
    seen.add(key);
  }
}

/** 校验「接口名 → { constructorParent, prototypeParent, members }」型数据表。 */
function checkInterfaceTable(table, spec, problems) {
  if (!Object.isFrozen(table)) {
    problems.push(`${spec.path}: ${spec.exportName} 必须冻结`);
  }
  const entries = Object.entries(table);
  if (entries.length === 0) {
    problems.push(`${spec.path}: ${spec.exportName} 不能为空`);
    return;
  }
  for (const [name, surface] of entries) {
    const label = `${spec.exportName}.${name}`;
    if (!isPlainObject(surface)) {
      problems.push(`${label}: 条目必须是对象`);
      continue;
    }
    for (const field of ['constructorParent', 'prototypeParent']) {
      if (typeof surface[field] !== 'string') {
        problems.push(`${label}: ${field} 必须是字符串`);
      }
    }
    checkMemberRows(surface.members, `${label}.members`, problems);
  }
}

function checkUniqueNames(rows, label, problems) {
  const seen = new Set();
  for (const row of rows) {
    if (!Array.isArray(row) || typeof row[0] !== 'string' || row[0] === '') {
      problems.push(`${label}: 条目必须是 [名称, 值] 数组`);
      continue;
    }
    if (seen.has(row[0])) problems.push(`${label}: 重复名称 ${row[0]}`);
    seen.add(row[0]);
  }
}

/** 校验 WebGL 数据表（accessors / constants / methods / members 四组）。 */
function checkWebglTable(table, spec, problems) {
  if (!Object.isFrozen(table)) {
    problems.push(`${spec.path}: ${spec.exportName} 必须冻结`);
  }
  const entries = Object.entries(table);
  if (entries.length === 0) {
    problems.push(`${spec.path}: ${spec.exportName} 不能为空`);
    return;
  }
  for (const [name, surface] of entries) {
    const label = `${spec.exportName}.${name}`;
    if (!isPlainObject(surface)) {
      problems.push(`${label}: 条目必须是对象`);
      continue;
    }
    for (const field of Object.keys(surface)) {
      if (!WEBGL_FIELDS.has(field)) {
        problems.push(`${label}: 未知字段 ${field}`);
      }
    }
    if (!Array.isArray(surface.accessors) || surface.accessors.length === 0) {
      problems.push(`${label}.accessors: 必须是非空数组`);
    } else if (surface.accessors.some(accessor => typeof accessor !== 'string' || accessor === '')) {
      problems.push(`${label}.accessors: 成员必须是字符串`);
    } else if (new Set(surface.accessors).size !== surface.accessors.length) {
      problems.push(`${label}.accessors: 成员重复`);
    }
    if (!Array.isArray(surface.methods) || surface.methods.length === 0) {
      problems.push(`${label}.methods: 必须是非空数组`);
    } else {
      checkMemberRows(
        surface.methods.map(([methodName, arity]) => ['method', methodName, arity]),
        `${label}.methods`,
        problems,
      );
    }
    if (!Array.isArray(surface.constants) || surface.constants.length === 0) {
      problems.push(`${label}.constants: 必须是非空数组`);
    } else {
      checkUniqueNames(surface.constants, `${label}.constants`, problems);
      for (const [, value] of surface.constants) {
        if (typeof value !== 'number' || !Number.isFinite(value)) {
          problems.push(`${label}.constants: 值必须是有限数字`);
          break;
        }
      }
    }
    checkMemberRows(surface.members, `${label}.members`, problems);
  }
}

async function collectSourceFiles(dir, prefix = '') {
  const entries = await readdir(dir, { withFileTypes: true });
  const files = [];
  for (const entry of entries) {
    if (entry.name === 'node_modules' || entry.name === '.git') continue;
    if (entry.isDirectory()) {
      files.push(...await collectSourceFiles(
        new URL(`${entry.name}/`, dir),
        `${prefix}${entry.name}/`,
      ));
    } else if (/\.(js|mjs)$/.test(entry.name)) {
      files.push({ path: `${prefix}${entry.name}`, url: new URL(entry.name, dir) });
    }
  }
  return files;
}

async function checkDanglingToolReferences(problems) {
  let scanned = 0;
  for (const directory of SCAN_DIRECTORIES) {
    const files = await collectSourceFiles(new URL(`${directory}/`, REPO_ROOT));
    scanned += files.length;
    for (const file of files) {
      const source = await readFile(file.url, 'utf8');
      for (const match of source.matchAll(TOOLS_REFERENCE)) {
        const toolPath = `tools/${match[1]}`;
        if (!existsSync(new URL(toolPath, REPO_ROOT))) {
          problems.push(`${file.path}: 引用了不存在的生成器 ${toolPath}`);
        }
      }
    }
  }
  return scanned;
}

async function checkDataTables(problems) {
  for (const spec of DATA_TABLES) {
    const module = await import(pathToFileURL(fileURLToPath(new URL(spec.path, REPO_ROOT))).href);
    const table = module[spec.exportName];
    if (!isPlainObject(table)) {
      problems.push(`${spec.path}: 缺少导出 ${spec.exportName}`);
      continue;
    }
    if (spec.shape === 'webgl') {
      checkWebglTable(table, spec, problems);
    } else {
      checkInterfaceTable(table, spec, problems);
    }
  }
}

async function checkFunctionArtifacts(problems) {
  for (const artifact of FUNCTION_ARTIFACTS) {
    const source = await readFile(new URL(artifact.path, REPO_ROOT), 'utf8');
    if (!source.includes(artifact.marker)) {
      problems.push(`${artifact.path}: 找不到导出标记 ${artifact.marker}...)`);
    }
  }
}

const problems = [];
const scannedFiles = await checkDanglingToolReferences(problems);
await checkDataTables(problems);
await checkFunctionArtifacts(problems);

if (problems.length > 0) {
  console.error(`check:generated 失败（${problems.length} 个问题）：`);
  for (const problem of problems) console.error(`  - ${problem}`);
  process.exitCode = 1;
} else {
  console.log(
    `check:generated 通过：扫描 ${scannedFiles} 个源文件，`
    + `校验 ${DATA_TABLES.length} 张数据表与 ${FUNCTION_ARTIFACTS.length} 个代码型生成物`,
  );
}
